//! `ntsc cargo doc` — show Neutron-facing docs for a Rust crate.

use std::path::Path;

use crate::cache;
use crate::{CargoError, CargoResult, adaptor};

/// Print Neutron docs for `name` (a Rust crate from `[rust-deps]`).
///
/// The source of truth is the export manifest `.ntsc/<crate>/<crate>.export.json`
/// generated by `adaptor::emit_adaptor`. When the manifest is absent we fall
/// back to the manifest/lock version info so `doc` remains useful before the
/// first build.
pub fn doc(project_dir: &Path, raw_name: &str) -> CargoResult<()> {
    generate_doc(project_dir, raw_name, BrowserAction::Open)
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum BrowserAction {
    Open,
    Skip,
}

pub(crate) fn run(project_dir: &Path, args: &[String]) -> CargoResult<()> {
    let mut name = None;
    let mut browser = BrowserAction::Open;
    for arg in args {
        match arg.as_str() {
            "--no-open" => browser = BrowserAction::Skip,
            value if !value.starts_with('-') && name.is_none() => name = Some(value),
            _ => {
                return Err(CargoError(
                    "usage: ntsc cargo doc <crate> [--no-open]".into(),
                ));
            }
        }
    }
    let name =
        name.ok_or_else(|| CargoError("usage: ntsc cargo doc <crate> [--no-open]".into()))?;
    generate_doc(project_dir, name, browser)
}

fn generate_doc(project_dir: &Path, raw_name: &str, browser: BrowserAction) -> CargoResult<()> {
    let requested = raw_name.trim().trim_start_matches('@').trim();
    if requested.is_empty() {
        return Err(CargoError("usage: ntsc cargo doc <crate>".into()));
    }

    let manifest_path = project_dir.join("neutron.toml");
    let manifest = crate::manifest::Manifest::read(&manifest_path).ok();
    let locked = crate::manifest::read_lock(project_dir).ok().flatten();
    // Cargo package names may contain hyphens, while Neutron namespaces use
    // underscores. Accept either spelling at the command line, but retain the
    // package spelling for cache, lockfile, and export paths.
    let name = manifest
        .as_ref()
        .and_then(|m| dependency_name(m, requested))
        .unwrap_or_else(|| requested.to_string());
    let module_name = neutron_module_name(&name);

    let spec = manifest
        .as_ref()
        .and_then(|m| m.rust_deps.get(&name))
        .map(|s| s.display());
    let locked_version = locked.as_ref().and_then(|l| l.version_for(&name));

    let deps_dir = cache::project_deps_dir(project_dir);
    let export_path = deps_dir.join(&name).join(format!("{name}.export.json"));
    let export_exists = export_path.is_file();

    if !export_exists && spec.is_none() && locked_version.is_none() {
        if is_builtin_module(requested) {
            println!("`{requested}` is a Neutron stdlib module, not a Rust crate.");
            println!("Try: grep -R \"{requested}\" --include=\"*.nt\" or see docs/stdlib.md");
            return Ok(());
        }
        return Err(CargoError(format!(
            "crate `{name}` not found in [rust-deps] and no export manifest at {} — run `ntsc cargo install {name}` first",
            export_path.display()
        )));
    }

    // Header — crate identity in Neutron terms.
    println!("crate {name} (Neutron module @{module_name})");
    if let Some(spec) = &spec {
        println!("  spec: {spec}");
    }
    if let Some(version) = locked_version {
        println!("  locked: {version}");
    } else if spec.is_some() {
        println!("  locked: (unresolved — run `ntsc cargo install {name}`)");
    }
    println!("  import: use @{module_name}");
    let alias_example = format!("use @{module_name} as {}", short_alias(&module_name));
    println!("  alias:  {alias_example}");
    println!();

    // Only the generated manifest describes what the current adaptor exposes.
    // Source discovery can differ by version or features, so never use it to
    // overwrite a built API while viewing its documentation.
    if export_exists {
        let content = std::fs::read_to_string(&export_path)?;
        let value: serde_json::Value = serde_json::from_str(&content).map_err(|error| {
            CargoError(format!(
                "cannot parse {}: {error} — run `ntsc build` to regenerate it",
                export_path.display()
            ))
        })?;
        println!("{}", manifest_summary(&value));
        println!("  source: {}", export_path.display());
        println!("  refresh: ntsc build");
        let html = format_export_html(&content, locked_version);
        let out_path = deps_dir.join(&name).join(format!("{name}.export.html"));
        std::fs::write(&out_path, html)?;
        println!("wrote {}", out_path.display());
        if browser == BrowserAction::Open {
            open_in_browser(&out_path)?;
        }
        return Ok(());
    }

    let mut live = Vec::new();
    if let Some(manifest) = manifest.as_ref()
        && manifest.rust_deps.contains_key(&name)
    {
        // Preferred source is the `~/.ntsc/cargo` cache; fall back to
        // `~/.cargo` registry.
        if let Some(locked) = locked.as_ref().and_then(|l| l.version_for(&name)) {
            let cache_root = cache::CacheRoot::from_env();
            let cached_src = cache_root.crate_src_path(&name, locked);
            if cached_src.is_dir() {
                live = adaptor::discover_public_functions(&cached_src);
            }
        }
        if live.is_empty() {
            // Fall back to the cargo registry src (e.g. `~/.cargo/registry`).
            let cargo_home = std::env::var_os("CARGO_HOME")
                .map(std::path::PathBuf::from)
                .unwrap_or_else(|| {
                    std::env::var_os("HOME")
                        .map(std::path::PathBuf::from)
                        .unwrap_or_else(|| std::path::PathBuf::from("."))
                        .join(".cargo")
                        .join("registry")
                        .join("src")
                });
            // Walk the registry src for the crate.
            if let Ok(entries) = std::fs::read_dir(&cargo_home) {
                for host in entries.flatten() {
                    let candidate = host.path().join(format!("{name}-*"));
                    // We don't have glob, so just check if any dir starts with `name-`.
                    if let Ok(host_entries) = std::fs::read_dir(host.path()) {
                        for e in host_entries.flatten() {
                            if e.file_name()
                                .to_string_lossy()
                                .starts_with(&format!("{name}-"))
                            {
                                let src = e.path();
                                let mut found = adaptor::discover_public_functions(&src);
                                if !found.is_empty() {
                                    live.append(&mut found);
                                }
                            }
                        }
                    }
                    let _ = candidate;
                }
            }
            // Also try the `~/.cargo/registry/src` without host subdir (some setups).
            if live.is_empty()
                && let Ok(entries) = std::fs::read_dir(&cargo_home)
            {
                for e in entries.flatten() {
                    if e.file_name()
                        .to_string_lossy()
                        .starts_with(&format!("{name}-"))
                    {
                        let mut found = adaptor::discover_public_functions(&e.path());
                        if !found.is_empty() {
                            live.append(&mut found);
                        }
                    }
                }
            }
        }
    }
    // De-duplicate live.
    {
        let mut seen = std::collections::HashSet::new();
        let mut uniq = Vec::new();
        for f in live.clone() {
            if seen.insert(f.name.clone()) {
                uniq.push(f);
            }
        }
        live = uniq;
    }

    if !live.is_empty() {
        println!("(no export manifest yet at {})", export_path.display());
        println!("Source API preview (not a generated adaptor; default-feature discovery):\n");
        for f in &live {
            println!(
                "  @{module_name}.{}({}) -> {}{}",
                f.name,
                format_params(&f.params),
                ret_label(&f.ret),
                if f.is_async {
                    "  (call with await)"
                } else {
                    ""
                }
            );
        }
        println!("\nRun `ntsc cargo install {name}` or `ntsc build` to generate the export.");
    } else {
        println!("(no export manifest yet at {})", export_path.display());
        println!("Run `ntsc cargo install {name}` or `ntsc build` to generate it.");
        println!();
        println!("No exported functions are available until the crate is installed and adapted.");
    }

    Ok(())
}

fn manifest_summary(value: &serde_json::Value) -> String {
    let functions = value
        .get("functions")
        .and_then(serde_json::Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or(&[]);
    let typed = functions
        .iter()
        .filter(|function| {
            function
                .get("status")
                .and_then(|s| s.as_str())
                .unwrap_or("typed")
                == "typed"
        })
        .count();
    let async_count = functions
        .iter()
        .filter(|function| {
            function
                .get("status")
                .and_then(|s| s.as_str())
                .unwrap_or("typed")
                == "typed"
                && function.get("async").and_then(|a| a.as_bool()) == Some(true)
        })
        .count();
    let unsupported = functions.len().saturating_sub(typed);
    let callbacks = value
        .get("callbacks")
        .and_then(serde_json::Value::as_array)
        .map_or(0, Vec::len);
    format!(
        "API: {} callable functions ({} synchronous, {} async), {} not exposed, {} callbacks",
        typed,
        typed.saturating_sub(async_count),
        async_count,
        unsupported,
        callbacks
    )
}

fn dependency_name(manifest: &crate::manifest::Manifest, requested: &str) -> Option<String> {
    manifest
        .rust_deps
        .keys()
        .find(|name| **name == requested)
        .or_else(|| {
            manifest
                .rust_deps
                .keys()
                .find(|name| neutron_module_name(name) == neutron_module_name(requested))
        })
        .cloned()
}

fn neutron_module_name(name: &str) -> String {
    name.replace('-', "_")
}

fn short_alias(name: &str) -> String {
    name.split(['_', '-']).next().unwrap_or(name).to_string()
}

/// Render a function's parameter list as `a0: string, a1: bytes, ...`.
fn format_params(params: &[adaptor::ParamKind]) -> String {
    params
        .iter()
        .enumerate()
        .map(|(i, kind)| format!("a{i}: {}", param_label(kind)))
        .collect::<Vec<_>>()
        .join(", ")
}

fn param_label(kind: &adaptor::ParamKind) -> String {
    adaptor::param_type_name(kind)
}

fn ret_label(kind: &adaptor::RetKind) -> String {
    adaptor::ret_type_name(kind)
}

fn is_builtin_module(name: &str) -> bool {
    // Keep in sync with `ntsc_typeck::names::BUILTIN_MODULES`.
    const BUILTIN: &[&str] = &[
        "archive",
        "arrays",
        "async",
        "collections",
        "csv",
        "crypto",
        "encoding",
        "fmt",
        "glob",
        "hash",
        "http",
        "io",
        "json",
        "math",
        "memory",
        "paths",
        "slices",
        "net",
        "os",
        "process",
        "random",
        "regex",
        "sort",
        "strings",
        "sys",
        "testing",
        "time",
        "toml",
        "yaml",
    ];
    BUILTIN.contains(&name)
}

/// Render a manifest type label in Neutron terms. Manifest labels contain
/// bridge implementation details (`object[foo::Bar]`, `result[string]`);
/// docs describe the values a Neutron program actually sees.
fn friendly_type(label: &str) -> String {
    if let Some(inner) = label
        .strip_prefix("result[")
        .and_then(|s| s.strip_suffix(']'))
    {
        return friendly_type(inner);
    }
    if let Some(inner) = label
        .strip_prefix("object[")
        .and_then(|s| s.strip_suffix(']'))
    {
        let _ = inner;
        return "object".to_string();
    }
    if let Some(inner) = label
        .strip_prefix("callback[")
        .and_then(|s| s.strip_suffix(']'))
    {
        let _ = inner;
        return "callback".to_string();
    }
    if let Some(inner) = label
        .strip_prefix("option[")
        .and_then(|s| s.strip_suffix(']'))
    {
        return format!("option[{}]", friendly_type(inner));
    }
    if let Some(inner) = label
        .strip_prefix("array[")
        .and_then(|s| s.strip_suffix(']'))
    {
        return format!("array[{}]", friendly_type(inner));
    }
    label.to_string()
}

/// Render a return label for the Returns column: `Result`-returning
/// functions list their success type; the throwing behavior is stated
/// once in the header instead of per row.
fn friendly_ret(label: &str) -> String {
    friendly_type(label)
}

/// Render the export manifest as a standalone HTML page with the same
/// grouping as the terminal view: one section per Rust module, a table
/// per section, and the crate's own `///` comments as descriptions.
fn format_export_html(content: &str, version: Option<&str>) -> String {
    let v: serde_json::Value = match serde_json::from_str(content) {
        Ok(v) => v,
        Err(_) => {
            return "<html><body><h1>invalid export manifest</h1>\
<p>Run <code>ntsc cargo install &lt;crate&gt;</code> to regenerate it.</p></body></html>"
                .to_string();
        }
    };
    let module = v.get("module").and_then(|m| m.as_str()).unwrap_or("?");
    let import_name = neutron_module_name(module);
    let funcs = v
        .get("functions")
        .and_then(|f| f.as_array())
        .cloned()
        .unwrap_or_default();
    let usable: Vec<&serde_json::Value> = funcs
        .iter()
        .filter(|f| f.get("status").and_then(|s| s.as_str()).unwrap_or("typed") == "typed")
        .collect();
    let unsupported: Vec<&serde_json::Value> = funcs
        .iter()
        .filter(|f| {
            !matches!(
                f.get("status").and_then(|s| s.as_str()).unwrap_or("typed"),
                "typed"
            )
        })
        // Generic impl blocks and private/internal types are discovery
        // diagnostics, not callable crate APIs. Keep unsupported public
        // functions and methods when a Rust signature is available.
        .filter(|f| f.get("signature").and_then(|s| s.as_str()).is_some())
        .collect();

    let mut sections = String::new();
    let mut navigation = String::new();
    let mut grouped: std::collections::BTreeMap<String, Vec<&serde_json::Value>> =
        std::collections::BTreeMap::new();
    for f in &usable {
        let group = if f.get("async").and_then(|a| a.as_bool()).unwrap_or(false) {
            "Async functions"
        } else {
            "Functions"
        };
        grouped.entry(group.to_string()).or_default().push(f);
    }
    for (section_index, (group, entries)) in grouped.into_iter().enumerate() {
        let section_id = format!("functions-{section_index}");
        navigation.push_str(&format!(
            "<a href=\"#{section_id}\">{}</a>",
            html_escape(&group)
        ));
        sections.push_str(&format!(
            "\n<section id=\"{section_id}\" data-api-section>\n<h2>{}</h2>\n<table>\n<thead><tr><th>Neutron call</th><th>Returns</th><th>Description</th></tr></thead>\n<tbody>\n",
            html_escape(&group)
        ));
        for f in entries {
            let name = f.get("name").and_then(|n| n.as_str()).unwrap_or("?");
            let is_async = f.get("async").and_then(|a| a.as_bool()).unwrap_or(false);
            let params = f
                .get("params")
                .and_then(|p| p.as_array())
                .map(|arr| {
                    arr.iter()
                        .enumerate()
                        .map(|(i, p)| {
                            let ty = p.get("type").and_then(|t| t.as_str()).unwrap_or("string");
                            let param_name = p.get("name").and_then(|n| n.as_str()).unwrap_or("");
                            let param_name = if param_name.is_empty() {
                                format!("a{i}")
                            } else {
                                param_name.to_string()
                            };
                            format!("{}: {}", param_name, friendly_type(ty))
                        })
                        .collect::<Vec<_>>()
                        .join(", ")
                })
                .unwrap_or_default();
            let ret_ty = f
                .get("return")
                .and_then(|r| r.get("type"))
                .and_then(|t| t.as_str())
                .unwrap_or("string");
            let doc = f.get("doc").and_then(|d| d.as_str()).unwrap_or("");
            let call = if is_async {
                format!("await @{import_name}.{name}({params})")
            } else {
                format!("@{import_name}.{name}({params})")
            };
            let error_note = if ret_ty.starts_with("result[") {
                "<small class=\"throws\">throws on Rust error</small>"
            } else {
                ""
            };
            sections.push_str(&format!(
                "<tr data-api-entry>\n<td><code>{}</code></td>\n<td><code>{}</code>{}</td>\n<td class=\"doc\">{}</td>\n</tr>\n",
                html_escape(&call),
                html_escape(&friendly_ret(ret_ty)),
                error_note,
                render_markdown(doc)
            ));
        }
        sections.push_str("</tbody>\n</table>\n</section>\n");
    }
    if let Some(callbacks) = v.get("callbacks").and_then(|c| c.as_array())
        && !callbacks.is_empty()
    {
        navigation.push_str("<a href=\"#callbacks\">Callbacks</a>");
        sections.push_str("\n<section id=\"callbacks\" data-api-section>\n<h2>Callbacks</h2>\n<p>This crate can invoke the listed callback methods. Register the generated callback type at the crate entry point; methods receive these Neutron values and run asynchronously.</p>\n");
        for callback in callbacks {
            let trait_name = callback
                .get("trait")
                .and_then(|t| t.as_str())
                .unwrap_or("callback");
            sections.push_str(&format!(
                "<h3><code>{}</code></h3>\n<ul>\n",
                html_escape(trait_name)
            ));
            if let Some(methods) = callback.get("methods").and_then(|m| m.as_array()) {
                for method in methods {
                    let method_name = method
                        .get("name")
                        .and_then(|n| n.as_str())
                        .unwrap_or("method");
                    let params = method
                        .get("params")
                        .and_then(|p| p.as_array())
                        .map(|params| {
                            params
                                .iter()
                                .enumerate()
                                .map(|(i, ty)| {
                                    let ty = ty.as_str().unwrap_or("object");
                                    format!("a{i}: {}", friendly_type(ty))
                                })
                                .collect::<Vec<_>>()
                                .join(", ")
                        })
                        .unwrap_or_default();
                    sections.push_str(&format!(
                        "<li data-api-entry><code>{}({})</code></li>\n",
                        html_escape(method_name),
                        params
                    ));
                }
            }
            sections.push_str("</ul>\n");
        }
        sections.push_str("</section>\n");
    }
    let unsupported_html = if unsupported.is_empty() {
        String::new()
    } else {
        let mut by_reason: std::collections::BTreeMap<&str, usize> =
            std::collections::BTreeMap::new();
        for function in &unsupported {
            *by_reason
                .entry(
                    function
                        .get("reason")
                        .and_then(|r| r.as_str())
                        .unwrap_or("unsupported"),
                )
                .or_default() += 1;
        }
        let summary = by_reason
            .iter()
            .map(|(reason, count)| {
                format!(
                    "<li><strong>{}</strong>: {}</li>\n",
                    count,
                    html_escape(reason)
                )
            })
            .collect::<String>();
        let items = unsupported
            .iter()
            .take(80)
            .map(|f| {
                let name = f.get("name").and_then(|n| n.as_str()).unwrap_or("?");
                let status = f
                    .get("status")
                    .and_then(|s| s.as_str())
                    .unwrap_or("unsupported");
                let reason = f.get("reason").and_then(|r| r.as_str()).unwrap_or("");
                let detail = if reason.is_empty() {
                    String::new()
                } else {
                    format!(" — {}", html_escape(reason))
                };
                let signature = f
                    .get("signature")
                    .and_then(|s| s.as_str())
                    .map(|s| format!("<br><code>{}</code>", html_escape(s)))
                    .unwrap_or_default();
                format!(
                    "<li data-api-entry><code>@{}.{}()</code> <em>({})</em>{}{}</li>",
                    html_escape(&import_name),
                    html_escape(name),
                    html_escape(status),
                    detail,
                    signature
                )
            })
            .collect::<String>();
        let remainder = unsupported.len().saturating_sub(80);
        navigation.push_str("<a href=\"#not-exposed\">Not exposed</a>");
        format!(
            "\n<section id=\"not-exposed\" data-api-section><h2>Not exposed</h2><p>{} public Rust API item(s) use signatures the generic bridge cannot represent yet. This is a capability report, not a list of missing Serenity-specific bindings.</p><ul>{}</ul><details><summary>First {} unsupported items</summary><ul>{}</ul>{}</details></section>\n",
            unsupported.len(),
            summary,
            unsupported.len().min(80),
            items,
            if remainder == 0 {
                String::new()
            } else {
                format!(
                    "<p>{} more items omitted; inspect the export JSON for the complete report.</p>",
                    remainder
                )
            },
        )
    };
    let version_html = version
        .map(|v| format!(" <span class=\"version\">{}</span>", html_escape(v)))
        .unwrap_or_default();
    format!(
        "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>{module} - Neutron crate doc</title>\n<style>\
:root {{ color-scheme: light dark; }}\
body {{ font-family: system-ui, sans-serif; margin: 2rem auto; max-width: 80rem; padding: 0 1.5rem; line-height: 1.5; }}\
h1 {{ margin-bottom: 0; }} .version {{ color: gray; font-weight: normal; font-size: .7em; }}\
.toolbar {{ position: sticky; top: 0; z-index: 1; display: flex; gap: 1rem; align-items: center; flex-wrap: wrap; padding: .7rem 0; background: Canvas; }}\
.toolbar input {{ min-width: min(32rem, 80vw); padding: .45rem .6rem; border: 1px solid #8888; border-radius: 4px; background: Canvas; color: CanvasText; }}\
nav {{ display: flex; gap: .8rem; flex-wrap: wrap; }}\
nav a {{ color: LinkText; }}\
section {{ margin-top: 2.5rem; scroll-margin-top: 5rem; }}\
h2 {{ border-bottom: 1px solid #8883; padding-bottom: .3rem; }}\
table {{ border-collapse: collapse; width: 100%; table-layout: fixed; }}\
th, td {{ text-align: left; padding: .5rem .7rem; border-bottom: 1px solid #8884; vertical-align: top; overflow-wrap: anywhere; }}\
th:first-child, td:first-child {{ width: 40%; }}\
th:nth-child(2), td:nth-child(2) {{ width: 14%; }}\
td.doc p {{ margin: .2em 0; }}\
td.doc pre.code {{ white-space: pre-wrap; padding: .6rem; border-radius: 5px; background: #1b2b34; overflow-x: auto; }}\
td.doc ul {{ margin: .2em 0; padding-left: 1.2em; }}\
code {{ background: #8882; padding: 0 .3em; border-radius: 3px; }}\
.rust-reference {{ color: #666; font-size: .95em; }}\
.throws {{ display: block; color: #b45309; font-size: .85em; margin-top: .25rem; }}\
.empty-filter {{ display: none; color: gray; }}\
</style>\n</head>\n<body>\n<h1>{module}{version_html}</h1>\n<p>Import this dependency with <code>use @{import_name}</code>. Calls use <code>@{import_name}.function(...)</code>; async entries must be called with <code>await</code>. Rust <code>Result</code> errors are raised by the bridge, so the return column shows the success value.</p>\n<div class=\"toolbar\"><label for=\"api-filter\">Filter API</label><input id=\"api-filter\" type=\"search\" placeholder=\"function, parameter, or description\" autocomplete=\"off\"><nav>{navigation}</nav><span id=\"empty-filter\" class=\"empty-filter\">No matching entries</span></div>\n{sections}\n{unsupported_html}\n<script>\nconst filter = document.getElementById('api-filter');\nconst empty = document.getElementById('empty-filter');\nfilter.addEventListener('input', () => {{\n  const query = filter.value.trim().toLowerCase();\n  let visible = 0;\n  for (const row of document.querySelectorAll('[data-api-entry]')) {{\n    const matches = !query || row.textContent.toLowerCase().includes(query);\n    row.hidden = !matches;\n    if (matches) visible++;\n  }}\n  empty.style.display = query && visible === 0 ? 'inline' : 'none';\n}});\n</script>\n</body>\n</html>\n",
        module = html_escape(module),
        import_name = html_escape(&import_name),
    )
}

/// Escape a string for safe interpolation into HTML text content.
fn html_escape(text: &str) -> String {
    text.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

/// Render a Rust doc comment (CommonMark) to HTML. Fenced examples from a Rust
/// crate are intentionally omitted: they are not valid Neutron programs.
fn render_markdown(text: &str) -> String {
    if text.is_empty() {
        return String::new();
    }
    let text = text
        .replace(
            "Call `.into_owned()` if you need a `String`",
            "The bridge returns an owned Neutron string",
        )
        .replace(
            "Call `.into_owned()` if you need a `Vec` or `String`",
            "The bridge returns an owned Neutron value",
        );
    let parser = pulldown_cmark::Parser::new(&text);
    let mut html = String::new();
    pulldown_cmark::html::push_html(&mut html, parser);
    strip_code_blocks(html)
}

fn strip_code_blocks(mut html: String) -> String {
    while let Some(start) = html.find("<pre><code") {
        let Some(end_rel) = html[start..].find("</code></pre>") else {
            break;
        };
        let end = start + end_rel + "</code></pre>".len();
        html.replace_range(
            start..end,
            "<p class=\"rust-reference\"><em>Rust reference example omitted; use the Neutron call shown above.</em></p>",
        );
    }
    html
}

/// Open a file in the system browser. Best effort: prints the path when
/// no opener exists on the platform.
fn open_in_browser(path: &Path) -> CargoResult<()> {
    let url = format!("file://{}", path.display());
    let opened = if cfg!(target_os = "macos") {
        std::process::Command::new("open").arg(&url).spawn().is_ok()
    } else if cfg!(target_os = "windows") {
        std::process::Command::new("cmd")
            .args(["/C", "start", "", &url])
            .spawn()
            .is_ok()
    } else {
        ["xdg-open", "gio", "wslview"].iter().any(|program| {
            std::process::Command::new(program)
                .arg(&url)
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null())
                .spawn()
                .is_ok()
        })
    };
    if opened {
        Ok(())
    } else {
        println!("open it manually: {}", path.display());
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;

    struct TempDir(PathBuf);
    impl TempDir {
        fn new(tag: &str) -> Self {
            let dir = std::env::temp_dir().join(format!(
                "ntsc_doc_test_{tag}_{}_{}",
                std::process::id(),
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .map(|d| d.subsec_nanos())
                    .unwrap_or(0)
            ));
            std::fs::create_dir_all(&dir).unwrap();
            Self(dir)
        }
    }
    impl Drop for TempDir {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }

    #[test]
    fn doc_requires_name() {
        let proj = TempDir::new("empty");
        let err = doc(&proj.0, "").unwrap_err();
        assert!(err.0.contains("usage"));
    }

    #[test]
    fn doc_rejects_unknown_crate() {
        let proj = TempDir::new("unknown");
        // Need a neutron.toml so Manifest::read succeeds.
        std::fs::write(
            proj.0.join("neutron.toml"),
            "[package]\nentry=\"src/main.nt\"\noutput=\"app\"\n",
        )
        .unwrap();
        let err = doc(&proj.0, "nope").unwrap_err();
        assert!(err.0.contains("not found"));
    }

    #[test]
    fn doc_prints_export_when_present() {
        let proj = TempDir::new("present");
        std::fs::write(
            proj.0.join("neutron.toml"),
            "[package]\nentry=\"src/main.nt\"\noutput=\"app\"\n\n[rust-deps]\nfoo=\"1.0\"\n",
        )
        .unwrap();
        let deps = proj.0.join(".ntsc").join("foo");
        std::fs::create_dir_all(&deps).unwrap();
        std::fs::write(
            deps.join("foo.export.json"),
            r#"{"module":"foo","functions":[{"name":"parse","params":[{"name":"input","tier":1,"type":"string"}],"return":{"tier":1,"type":"string"},"symbol":"ntsc_adaptor_foo_parse"}],"types":[],"enums":[]}"#,
        )
        .unwrap();
        // Should succeed and print (we just check it does not error).
        doc(&proj.0, "foo").unwrap();
        doc(&proj.0, "@foo").unwrap();
    }

    #[test]
    fn hyphenated_crates_use_neutron_namespaces() {
        let manifest =
            crate::manifest::Manifest::parse("[rust-deps]\nmewsic-tui = \"1\"\nother = \"1\"\n")
                .unwrap();
        assert_eq!(
            dependency_name(&manifest, "mewsic_tui"),
            Some("mewsic-tui".to_string())
        );
        assert_eq!(neutron_module_name("mewsic-tui"), "mewsic_tui");

        let html = format_export_html(
            r#"{"module":"mewsic-tui","functions":[{"name":"ping","status":"typed","params":[],"return":{"type":"bool"}}]}"#,
            None,
        );
        assert!(html.contains("use @mewsic_tui"));
        assert!(html.contains("@mewsic_tui.ping()"));
        assert!(!html.contains("use @mewsic-tui"));
        assert!(html.contains("Filter API"));
    }

    #[test]
    fn export_html_uses_neutron_calls_and_omits_rust_examples() {
        let manifest = r#"{
            "module":"foo",
            "functions":[
                {
                    "name":"Thing_build",
                    "path":"nested::Thing::build",
                    "status":"typed",
                    "params":[{"name":"builder","tier":1,"type":"object[nested::Thing]"}],
                    "return":{"tier":1,"type":"result[string]"},
                    "async":false,
                    "doc":"Builds it.\n\n```rust\nuse foo::Thing;\n```"
                },
                {
                    "name":"Thing_build_async",
                    "path":"nested::Thing::build_async",
                    "status":"typed",
                    "params":[{"name":"builder","tier":1,"type":"object[nested::Thing]"}],
                    "return":{"tier":1,"type":"result[string]"},
                    "async":true,
                    "doc":"Offloaded asynchronous variant"
                },
                {"name":"InternalGeneric","path":"internal::InternalGeneric","status":"unsupported","reason":"generic impl blocks are not monomorphized"},
                {"name":"decode_raw","path":"decode_raw","status":"unsupported","reason":"public signature is outside the typed bridge ABI","signature":"fn decode_raw(data: &str) -> Cow<str>"}
            ],
            "callbacks":[],
            "types":[],
            "enums":[]
        }"#;

        let html = format_export_html(manifest, Some("1.0.0"));

        assert!(html.contains("use @foo"));
        assert!(html.contains("@foo.Thing_build(builder: object)"));
        assert!(html.contains("await @foo.Thing_build_async(builder: object)"));
        assert!(!html.contains("nested::Thing::build"));
        assert!(!html.contains("use foo::Thing"));
        assert!(!html.contains("into_owned"));
        assert!(!html.contains("tier 1"));
        assert!(html.contains("@foo.decode_raw()"));
        assert!(!html.contains("InternalGeneric"));
        assert!(html.lines().count() > 20);
    }

    #[test]
    fn export_html_does_not_invent_parse_or_stringify() {
        let manifest = r#"{
            "module":"urlencoding",
            "functions":[{
                "name":"encode",
                "path":"encode",
                "status":"typed",
                "params":[{"name":"text","tier":1,"type":"string"}],
                "return":{"tier":1,"type":"string"},
                "async":false
            }],
            "callbacks":[],
            "types":[],
            "enums":[]
        }"#;

        let html = format_export_html(manifest, None);

        assert!(html.contains("@urlencoding.encode(text: string)"));
        assert!(!html.contains("parse("));
        assert!(!html.contains("stringify("));
    }
}
